.expense-panel button:disabled { opacity: .5; cursor: not-allowed; }
.expense-panel button.expense-submit { justify-self: start; margin-top: 8px; background: #1d4ed8; border-color: #1d4ed8; color: white; }
.expense-panel p { line-height: 1.6; }
.expense-open { color: #15803d; }
.expense-hint { color: #64748b; }
.expense-error { padding: 12px; border-radius: 8px; color: #991b1b; background: #fef2f2; }
.expense-success { padding: 12px; border-radius: 8px; color: #166534; background: #f0fdf4; }
.expense-sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
